using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Gets the current server time in UTC")]
    public static string GetCurrentTime()
    {
        return DateTime.UtcNow.ToString("o");
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

